// Full lesson content and quiz for a module whose original data was a stub.
// One file per module in data/modules/expanded/<topic>/<module key>.ts;
// registered in ./index.ts (generated by scripts/learning/build-expansions-index.ts)
// and applied over the original module data in data/modules/index.ts.
import type { LearningLevel } from '@/types/learning'

export interface ExpandedLesson {
  /** Must match the original lesson's id */
  id: string
  title: string
  /** Lesson HTML per level */
  content: Record<LearningLevel, string>
}

export interface ExpandedQuizQuestion {
  id: string
  question: Record<LearningLevel, string>
  /** Four options per level; the correct one is at correctIndex for every level */
  options: Record<LearningLevel, string[]>
  correctIndex: number
  explanation: Record<LearningLevel, string>
}

export interface ModuleExpansion {
  topicId: string
  /** Module progress key (see moduleProgressKeys in lib/learning/topicVolumes.ts) */
  moduleKey: string
  lessons: ExpandedLesson[]
  /** Exactly five questions */
  quiz: ExpandedQuizQuestion[]
}
